package org.springframework.samples.petclinic.rest.controller.v1;

import java.time.LocalDate;
import java.util.Collection;
import java.util.List;
import java.util.Locale;
import java.util.OptionalInt;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.audit.AuditEventPublisher;
import org.springframework.samples.petclinic.audit.OwnerCreatedEvent;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.mapper.PetMapper;
import org.springframework.samples.petclinic.mapper.VisitMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.model.Pet;
import org.springframework.samples.petclinic.model.Visit;
import org.springframework.samples.petclinic.notify.WelcomeNotifier;
import org.springframework.samples.petclinic.rest.api.OwnersApi;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.PetDto;
import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
import org.springframework.samples.petclinic.rest.dto.VisitDto;
import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
import org.springframework.samples.petclinic.rest.validation.CityCapacityExceededException;
import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitExceededException;
import org.springframework.samples.petclinic.rest.validation.DuplicateIdentityException;
import org.springframework.samples.petclinic.rest.validation.MissingRequiredFieldsException;
import org.springframework.samples.petclinic.rest.validation.OwnerEmail;
import org.springframework.samples.petclinic.rest.validation.OwnerPostcode;
import org.springframework.samples.petclinic.rest.validation.OwnerRegistrationDate;
import org.springframework.samples.petclinic.rest.validation.OwnerTelephone;
import org.springframework.samples.petclinic.rest.validation.RequiredOwnerFields;
import org.springframework.samples.petclinic.service.ClinicService;
import org.springframework.samples.petclinic.util.AddressNormalizer;
import org.springframework.samples.petclinic.util.BusinessDays;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.util.UriComponentsBuilder;

import jakarta.transaction.Transactional;

/**
 * @author Vitaliy Fedoriv
 */

@RestController
@CrossOrigin(exposedHeaders = "errors, content-type")
@RequestMapping("/api")
public class OwnerRestControllerV1 implements OwnersApi {

    /** Maximum number of owners a single city may contain; creating another owner there is rejected. */
    static final int CITY_CAPACITY = 50;

    /** Owners already in a city at or above which (and below {@link #CITY_CAPACITY}) a new owner there gets 'capacityWarning'. */
    static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;

    /** Maximum number of owners that may be created per (business-day adjusted) registration date; further creates are rejected. */
    static final int DAILY_OWNER_LIMIT = 100;

    /** Owners already created on the same registration date beyond which a new owner gets 'bulkSignupWarning'. */
    static final int BULK_SIGNUP_THRESHOLD = 80;

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    private final PetMapper petMapper;

    private final VisitMapper visitMapper;

    private final AuditEventPublisher auditEventPublisher;

    private final WelcomeNotifier welcomeNotifier;

    public OwnerRestControllerV1(ClinicService clinicService,
                                 OwnerMapper ownerMapper,
                                 PetMapper petMapper,
                                 VisitMapper visitMapper,
                                 AuditEventPublisher auditEventPublisher,
                                 WelcomeNotifier welcomeNotifier) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
        this.auditEventPublisher = auditEventPublisher;
        this.welcomeNotifier = welcomeNotifier;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
        // A repeated create with an already-seen key returns the originally created owner.
        if (idempotencyKey != null) {
            Owner existing = this.clinicService.findOwnerByIdempotencyKey(idempotencyKey);
            if (existing != null) {
                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), ownerLocation(existing), HttpStatus.OK);
            }
        }
        List<String> missingFields = RequiredOwnerFields.missingFields(ownerFieldsDto);
        if (!missingFields.isEmpty()) {
            throw new MissingRequiredFieldsException(missingFields);
        }
        OwnerPostcode.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
        OwnerEmail.validate(ownerFieldsDto.getEmail());
        OwnerRegistrationDate.validate(ownerFieldsDto.getRegistrationDate());
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        owner.setTelephone(OwnerTelephone.normalize(ownerFieldsDto.getTelephone()));
        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
        applyAddress(owner, ownerFieldsDto);
        // Duplicate detection uses the identity key alone (telephone, email, soundex of the last name).
        owner.setHouseholdId(this.clinicService.householdIdOf(owner));
        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
        if (this.clinicService.ownerIdentityKeyExists(owner)) {
            throw new DuplicateIdentityException(owner.getIdentityKey());
        }
        long ownersInCity = this.clinicService.countOwnersInCity(ownerFieldsDto.getCity());
        if (ownersInCity >= CITY_CAPACITY) {
            throw new CityCapacityExceededException(ownerFieldsDto.getCity(), CITY_CAPACITY);
        }
        owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
        LocalDate registrationDate = BusinessDays.rollForward(
            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
        long ownersCreatedToday = this.clinicService.countOwnersRegisteredOn(registrationDate);
        if (ownersCreatedToday >= DAILY_OWNER_LIMIT) {
            throw new DailyOwnerLimitExceededException(DAILY_OWNER_LIMIT);
        }
        owner.setRegistrationDate(registrationDate);
        owner.setBulkSignupWarning(ownersCreatedToday > BULK_SIGNUP_THRESHOLD);
        // A declared household member is not a suspected duplicate.
        owner.setPossibleDuplicateOf(declaredHouseholdMember ? null : this.clinicService.findPossibleDuplicateOf(owner));
        owner.setIdempotencyKey(idempotencyKey);
        // The level cannot exceed one above the highest level among the existing household members.
        OptionalInt maxHouseholdLevel = this.clinicService.findHouseholdMembers(owner).stream()
            .mapToInt(ownerMapper::toMembershipLevel)
            .max();
        owner.setMembershipLevelCap(maxHouseholdLevel.isPresent() ? maxHouseholdLevel.getAsInt() + 1 : null);
        this.clinicService.saveOwner(owner);
        AUDIT.info("Owner created: id={}, memberId={}, region={}, fiscalYear={}, "
                + "registrationDate={}, membershipPoints={}, membershipLevel={}",
            owner.getId(), owner.getMemberId(), ownerMapper.toLocality(owner), ownerMapper.toFiscalYear(owner),
            owner.getRegistrationDate(), ownerMapper.toMembershipPoints(owner), ownerMapper.toMembershipLevel(owner));
        OwnerCreatedEvent created = this.auditEventPublisher.ownerCreated(owner, ownerMapper.toMembershipLevel(owner));
        this.welcomeNotifier.welcome(created);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), ownerLocation(owner), HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        String telephone = OwnerTelephone.normalize(ownerFieldsDto.getTelephone());
        OwnerPostcode.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
        OwnerEmail.validate(ownerFieldsDto.getEmail());
        OwnerRegistrationDate.validate(ownerFieldsDto.getRegistrationDate());
        applyAddress(currentOwner, ownerFieldsDto);
        currentOwner.setCity(ownerFieldsDto.getCity());
        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
        currentOwner.setLastName(ownerFieldsDto.getLastName());
        currentOwner.setTelephone(telephone);
        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
        if (ownerFieldsDto.getRegistrationDate() != null) {
            currentOwner.setRegistrationDate(BusinessDays.rollForward(ownerFieldsDto.getRegistrationDate()));
        }
        if (ownerFieldsDto.getBirthDate() != null) {
            currentOwner.setBirthDate(ownerFieldsDto.getBirthDate());
        }
        currentOwner.setTitle(ownerFieldsDto.getTitle() == null ? null : ownerFieldsDto.getTitle().getValue());
        this.clinicService.saveOwner(currentOwner);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        this.clinicService.deleteOwner(owner);
        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        HttpHeaders headers = new HttpHeaders();
        Pet pet = petMapper.toPet(petFieldsDto);
        owner.setId(ownerId);
        pet.setOwner(owner);
        pet.getType().setName(null);
        this.clinicService.savePet(pet);
        PetDto petDto = petMapper.toPetDto(pet);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
            .buildAndExpand(pet.getId()).toUri());
        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner != null) {
            Pet currentPet = this.clinicService.findPetById(petId);
            if (currentPet != null) {
                currentPet.setBirthDate(petFieldsDto.getBirthDate());
                currentPet.setName(petFieldsDto.getName());
                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
                this.clinicService.savePet(currentPet);
                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Visit visit = visitMapper.toVisit(visitFieldsDto);
        Pet pet = new Pet();
        pet.setId(petId);
        visit.setPet(pet);
        this.clinicService.saveVisit(visit);
        VisitDto visitDto = visitMapper.toVisitDto(visit);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
            .buildAndExpand(visit.getId()).toUri());
        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
    }


    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner != null) {
            Pet pet = owner.getPet(petId);
            if (pet != null) {
                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    /**
     * Stores the normalized structured address lines (absent when not supplied) and the composed
     * 'address': the structured lines when 'addressLine1' is present, otherwise the flat address.
     */
    private static void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
        owner.setAddressLine1(AddressNormalizer.normalizeOptional(ownerFieldsDto.getAddressLine1()));
        owner.setAddressLine2(owner.getAddressLine1() == null ? null
            : AddressNormalizer.normalizeOptional(ownerFieldsDto.getAddressLine2()));
        owner.setAddress(AddressNormalizer.compose(
            ownerFieldsDto.getAddressLine1(), ownerFieldsDto.getAddressLine2(), ownerFieldsDto.getAddress()));
    }

    private static HttpHeaders ownerLocation(Owner owner) {
        HttpHeaders headers = new HttpHeaders();
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return headers;
    }

    private static String normalizeEmail(String email) {
        return email == null ? null : email.toLowerCase(Locale.ROOT);
    }
}
package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;

/** risk-flag: Return 'riskFlag' true when any of these hold: the owner is a possible duplicate, the emai... */
class AcceptanceTest extends AcceptanceBase {

	@Test
	void coreRiskFlagFalseNormally() throws Exception {
		int id = createOwnerOk(structuredOwner());
		getOwner(id).andExpect(jsonPath("$.riskFlag").value(false));
	}
}
package org.springframework.samples.petclinic.acceptance;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.http.MediaType;
import org.springframework.security.test.context.support.WithMockUser;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;
import org.springframework.transaction.annotation.Transactional;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.node.ObjectNode;

/**
 * Experimenter-owned, black-box acceptance base for PetClinic-Evolve.
 *
 * <p>Every checkpoint is a business rule on the ONE endpoint {@code POST /api/owners};
 * tests create owners and read fields back via {@code GET /api/owners/{id}}, so the
 * Spring and OfficeFloor arms are judged by identical externals.
 *
 * <p>Isolation: {@code @Transactional} rolls each test back, so count/quota rules
 * (membership number, per-day cap, per-city cap, "most common city") see only the
 * seed data plus what the test itself creates — deterministic without polluting
 * other tests. {@code @WithMockUser} authenticates as a fixed admin so the audit
 * rules can assert a known user name.
 *
 * <p>Cumulative-safety convention: {@link #ownerNode()} returns a FULLY UNIQUE
 * owner, which every rule accepts (no duplicate, no quota) at every checkpoint;
 * tests then override only the fields needed to trigger a specific rule. Reject
 * cases use data that stays rejected under all later (broader) rules.
 */
@SpringBootTest
@AutoConfigureMockMvc
@Transactional
@WithMockUser(username = "acceptance-admin", roles = {"OWNER_ADMIN", "VET_ADMIN", "ADMIN"})
public abstract class AcceptanceBase {

	private static final AtomicInteger SEQ = new AtomicInteger(0);

	@Autowired
	protected MockMvc mvc;

	@Autowired
	protected ObjectMapper om;

	protected int seq() {
		return SEQ.incrementAndGet();
	}

	// --- unique generators (avoid colliding with seed data or other tests) ---

	/** Encode n as a lowercase letter string (1->a, 26->z, 27->aa), so generated
	 *  names satisfy the base app's letters-only owner-name pattern. */
	protected String letters(int n) {
		StringBuilder sb = new StringBuilder();
		for (int x = Math.max(n, 1); x > 0; x /= 26) {
			x--;
			sb.insert(0, (char) ('a' + x % 26));
		}
		return sb.toString();
	}

	/** Unique, letters-only surname (starts with "Sur"). */
	protected String uniqueLastName() {
		return "Sur" + letters(seq());
	}

	/** Unique, letters-only given name (starts with "Fn"). Use this instead of names like
	 *  "Mem"+i: the base app enforces a letters-only owner-name pattern, so a digit in a name is
	 *  rejected with 400. Being unique it also keeps namesakeCount at 0. */
	protected String uniqueFirstName() {
		return "Fn" + letters(seq());
	}

	protected String uniqueAddress() {
		return seq() + " Test Street";
	}

	protected String uniqueCity() {
		return "Town" + seq();
	}

	/** A unique 10-digit AU mobile ('04XXXXXXXX'). Chosen so the ONE payload stays valid across the
	 *  whole telephone rule chain: 10 digits satisfies the early normalize-to-10 rule; dropping the
	 *  leading '0' yields 9 national digits, which is exactly what the later E.164 '+61' form and the
	 *  per-country length rule (+61 => 9 national digits) require. Distinct from the +1 NANP seed data. */
	protected String uniqueTelephone() {
		return String.format("04%08d", seq());
	}

	protected String uniqueEmail() {
		return "owner" + seq() + "@example.test";
	}

	protected String today() {
		return LocalDate.now().toString();
	}

	// --- payloads -----------------------------------------------------------

	/** A fully valid, fully unique owner — accepted by every rule at every checkpoint. */
	protected ObjectNode ownerNode() {
		ObjectNode o = om.createObjectNode();
		o.put("firstName", "Test");
		o.put("lastName", uniqueLastName());
		o.put("address", uniqueAddress());
		o.put("city", uniqueCity());
		o.put("telephone", uniqueTelephone());
		return o;
	}

	/** Owner payload plus a postcode. "2000" is in the NSW range and is accepted by cities with no
	 *  known region (the permissive default), so it stays valid for the random cities ownerNode() makes. */
	protected ObjectNode withPostcode(ObjectNode o) {
		o.put("postcode", "2000");
		return o;
	}

	/** Owner with a STRUCTURED address (addressLine1 / city / postcode) for the later
	 *  checkpoints that replace the flat 'address' input with structured fields. */
	protected ObjectNode structuredOwner() {
		ObjectNode o = ownerNode();
		o.remove("address");
		o.put("addressLine1", seq() + " Test Street");
		o.put("postcode", "2000");
		return o;
	}

	// --- requests -----------------------------------------------------------

	protected String json(JsonNode node) {
		try {
			return om.writeValueAsString(node);
		}
		catch (Exception e) {
			throw new RuntimeException(e);
		}
	}

	protected ResultActions createOwner(JsonNode body) throws Exception {
		return mvc.perform(post("/api/owners").contentType(MediaType.APPLICATION_JSON)
				.content(json(body)));
	}

	protected int createOwnerOk(JsonNode body) throws Exception {
		return extractId(createOwner(body).andExpect(status().is2xxSuccessful()));
	}

	/** POST with an {@code Idempotency-Key} header (for the idempotent-create rule). */
	protected ResultActions createOwnerWithKey(JsonNode body, String key) throws Exception {
		return mvc.perform(post("/api/owners").contentType(MediaType.APPLICATION_JSON)
				.header("Idempotency-Key", key).content(json(body)));
	}

	/** Create {@code n} fully-unique owners (each accepted by every rule), all in the
	 *  SAME city — used to drive the per-city capacity/warning rules. Returns nothing;
	 *  each owner differs in name/address/telephone so only the city count accumulates. */
	protected void fillCity(String city, int n) throws Exception {
		for (int i = 0; i < n; i++) {
			ObjectNode o = ownerNode();
			o.put("city", city);
			createOwnerOk(o);
		}
	}

	/** Create {@code n} fully-unique owners (each accepted by every rule), all dated
	 *  today — used to drive the per-day create-limit / bulk-signup rules. */
	protected void createMany(int n) throws Exception {
		for (int i = 0; i < n; i++) {
			createOwnerOk(ownerNode());
		}
	}

	protected ResultActions getOwner(int id) throws Exception {
		return mvc.perform(get("/api/owners/" + id));
	}

	/** Soft-delete an owner via DELETE /api/owners/{id} (asserts 2xx). The record is retained,
	 *  flagged deleted, so the create endpoint's duplicate/identity checks ignore it. */
	protected void deleteOwner(int id) throws Exception {
		mvc.perform(delete("/api/owners/" + id)).andExpect(status().is2xxSuccessful());
	}

	/** GET the owner and return its JSON body (asserts 2xx). */
	protected JsonNode fetchOwner(int id) throws Exception {
		String body = getOwner(id).andExpect(status().is2xxSuccessful())
				.andReturn().getResponse().getContentAsString();
		return om.readTree(body);
	}

	protected int extractId(ResultActions ra) throws Exception {
		String body = ra.andReturn().getResponse().getContentAsString();
		if (body != null && !body.isBlank()) {
			JsonNode n = om.readTree(body);
			if (n.hasNonNull("id")) {
				return n.get("id").asInt();
			}
		}
		String location = ra.andReturn().getResponse().getHeader("Location");
		if (location != null && location.contains("/")) {
			return Integer.parseInt(location.substring(location.lastIndexOf('/') + 1));
		}
		throw new IllegalStateException("no id in create response: " + body);
	}

	// --- pinned reference data ------------------------------------------------
	// Shared, fixed ground truth for the LOOKUP-based rules (region, postcode,
	// timezone, holidays). The rule specs enumerate these same tables, so both
	// arms implement identical mappings and a test can assert an EXACT value
	// (e.g. locality "NSW" for Sydney) instead of merely that a field exists.

	/** City -> canonical region; anything not listed derives locality "UNKNOWN". */
	protected static final Map<String, String> CITY_REGION = Map.of(
			"Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

	/** Region -> IANA timezone. */
	protected static final Map<String, String> REGION_TIMEZONE = Map.of(
			"NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");

	/** Region -> inclusive 4-digit postcode range {low, high}. */
	protected static final Map<String, int[]> REGION_POSTCODES = Map.of(
			"NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

	/** Fixed public holidays the business-day roll skips (year of the run). */
	protected static final Set<LocalDate> HOLIDAYS = Set.of(
			LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
			LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));

	protected String region(String city) {
		return CITY_REGION.getOrDefault(city, "UNKNOWN");
	}

	protected String timezone(String city) {
		return REGION_TIMEZONE.get(region(city));
	}

	/** A postcode valid for the pinned city (low end of its region's range). */
	protected String validPostcode(String city) {
		int[] r = REGION_POSTCODES.get(region(city));
		return r == null ? null : String.valueOf(r[0]);
	}

	/** A fully-valid owner in a PINNED city with a valid postcode, so its region,
	 *  timezone and postcode-derived values are known exactly. */
	protected ObjectNode knownOwner(String city) {
		ObjectNode o = ownerNode();
		o.put("city", city);
		o.put("postcode", validPostcode(city));
		return o;
	}

	/** Roll a date forward over weekends and pinned holidays to the next business day. */
	protected LocalDate toBusinessDay(LocalDate d) {
		while (d.getDayOfWeek() == DayOfWeek.SATURDAY || d.getDayOfWeek() == DayOfWeek.SUNDAY
				|| HOLIDAYS.contains(d)) {
			d = d.plusDays(1);
		}
		return d;
	}

	// --- computed expectations ------------------------------------------------
	// Tests replicate the spec's algorithms exactly so they can assert the precise
	// derived value. The algorithms are standard (SHA-256, Luhn) and also stated in
	// the specs, so both arms produce identical outputs.

	/** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code s}. */
	protected static String sha256hex(String s) {
		try {
			byte[] digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
			StringBuilder sb = new StringBuilder(digest.length * 2);
			for (byte b : digest) {
				sb.append(String.format("%02x", b));
			}
			return sb.toString();
		}
		catch (Exception e) {
			throw new RuntimeException(e);
		}
	}

	/** First {@code n} UPPER-case hex characters of SHA-256({@code s}). */
	protected static String shaHex(String s, int n) {
		return sha256hex(s).substring(0, n).toUpperCase();
	}

	/** Luhn check digit (0-9) over the digits contained in {@code s}. */
	protected static int luhn(String s) {
		int sum = 0;
		boolean dbl = true;
		for (int i = s.length() - 1; i >= 0; i--) {
			char c = s.charAt(i);
			if (c < '0' || c > '9') {
				continue;
			}
			int d = c - '0';
			if (dbl) {
				d *= 2;
				if (d > 9) {
					d -= 9;
				}
			}
			sum += d;
			dbl = !dbl;
		}
		return (10 - (sum % 10)) % 10;
	}
